#!/bin/bash

# Auto Configuration Start Script for Get Notes MCP Server
# This script automatically configures environment variables and starts the MCP server

set -e  # Exit on any error

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
CONFIG_FILE="$PROJECT_ROOT/.env"

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

echo -e "${BLUE}🚀 Get Notes MCP Server Auto Configuration${NC}"
echo "=============================================="

# Function to prompt for input with default value
prompt_with_default() {
    local prompt_text="$1"
    local default_value="$2"
    local var_name="$3"
    
    if [ -n "$default_value" ]; then
        read -p "$prompt_text [$default_value]: " input
        export $var_name="${input:-$default_value}"
    else
        read -p "$prompt_text: " input
        export $var_name="$input"
    fi
}

# Function to load environment variables from .env file
load_env_file() {
    if [ -f "$CONFIG_FILE" ]; then
        echo -e "${GREEN}✓ Loading environment variables from .env file${NC}"
        export $(grep -v '^#' "$CONFIG_FILE" | xargs)
    else
        echo -e "${YELLOW}⚠ No .env file found, will prompt for configuration${NC}"
    fi
}

# Function to save environment variables to .env file
save_env_file() {
    echo "# Get Notes MCP Server Configuration" > "$CONFIG_FILE"
    echo "GET_NOTE_API_KEY=$GET_NOTE_API_KEY" >> "$CONFIG_FILE"
    echo "GET_NOTE_TOPIC_ID=$GET_NOTE_TOPIC_ID" >> "$CONFIG_FILE"
    
    if [ -n "$GET_NOTE_API_BASE_URL" ]; then
        echo "GET_NOTE_API_BASE_URL=$GET_NOTE_API_BASE_URL" >> "$CONFIG_FILE"
    fi
    
    if [ -n "$LOG_LEVEL" ]; then
        echo "LOG_LEVEL=$LOG_LEVEL" >> "$CONFIG_FILE"
    fi
    
    echo "# Transport configuration" >> "$CONFIG_FILE"
    echo "TRANSPORT_MODE=${TRANSPORT_MODE:-stdio}" >> "$CONFIG_FILE"
    echo "SERVER_PORT=${SERVER_PORT:-3000}" >> "$CONFIG_FILE"
    echo "SERVER_HOST=${SERVER_HOST:-localhost}" >> "$CONFIG_FILE"
    
    echo -e "${GREEN}✓ Configuration saved to .env file${NC}"
}

# Load existing configuration
load_env_file

# Prompt for API Key
if [ -z "$GET_NOTE_API_KEY" ] || [ "$GET_NOTE_API_KEY" = "your-api-key-here" ]; then
    echo -e "${YELLOW}⚠ API Key is required${NC}"
    prompt_with_default "Enter your Get Notes API Key" "" "GET_NOTE_API_KEY"
else
    echo -e "${GREEN}✓ Using existing API Key${NC}"
fi

# Prompt for Topic ID
if [ -z "$GET_NOTE_TOPIC_ID" ]; then
    prompt_with_default "Enter your Topic ID (optional)" "" "GET_NOTE_TOPIC_ID"
else
    echo -e "${GREEN}✓ Using existing Topic ID: $GET_NOTE_TOPIC_ID${NC}"
fi

# Prompt for API Base URL (optional)
if [ -z "$GET_NOTE_API_BASE_URL" ]; then
    prompt_with_default "Enter API Base URL (optional)" "https://open-api.biji.com/getnote/openapi" "GET_NOTE_API_BASE_URL"
else
    echo -e "${GREEN}✓ Using existing API Base URL: $GET_NOTE_API_BASE_URL${NC}"
fi

# Prompt for Log Level (optional)
if [ -z "$LOG_LEVEL" ]; then
    prompt_with_default "Enter Log Level (debug/info/warn/error)" "info" "LOG_LEVEL"
else
    echo -e "${GREEN}✓ Using existing Log Level: $LOG_LEVEL${NC}"
fi

# Prompt for Transport Mode
echo ""
echo "Transport Modes:"
echo "1) stdio - Standard Input/Output (default for Inspector)"
echo "2) sse   - Server-Sent Events"
echo "3) http  - HTTP REST API"
echo ""

current_transport="${TRANSPORT_MODE:-stdio}"
echo -e "${GREEN}Current transport mode: $current_transport${NC}"

case $current_transport in
    "sse")
        transport_choice=2
        ;;
    "http")
        transport_choice=3
        ;;
    *)
        transport_choice=1
        ;;
esac

read -p "Select transport mode (1-3) [${transport_choice}]: " input
transport_choice="${input:-$transport_choice}"

case $transport_choice in
    2)
        export TRANSPORT_MODE="sse"
        ;;
    3)
        export TRANSPORT_MODE="http"
        ;;
    *)
        export TRANSPORT_MODE="stdio"
        ;;
esac

echo -e "${GREEN}✓ Transport mode set to: $TRANSPORT_MODE${NC}"

# Prompt for Server Configuration (for SSE/HTTP modes)
if [ "$TRANSPORT_MODE" != "stdio" ]; then
    prompt_with_default "Enter Server Host" "${SERVER_HOST:-localhost}" "SERVER_HOST"
    prompt_with_default "Enter Server Port" "${SERVER_PORT:-3000}" "SERVER_PORT"
else
    export SERVER_HOST="localhost"
    export SERVER_PORT="3000"
fi

# Save configuration
save_env_file

# Create logs directory
mkdir -p "$PROJECT_ROOT/logs"

# Install dependencies if needed
if [ ! -d "$PROJECT_ROOT/node_modules" ]; then
    echo -e "${YELLOW}Installing dependencies...${NC}"
    cd "$PROJECT_ROOT"
    npm install
fi

# Build command arguments
CMD_ARGS=""
if [ "$TRANSPORT_MODE" != "stdio" ]; then
    CMD_ARGS="--transport $TRANSPORT_MODE --port $SERVER_PORT --host $SERVER_HOST"
fi

# Display configuration summary
echo ""
echo -e "${BLUE}📋 Configuration Summary:${NC}"
echo "=============================================="
echo -e "API Key: ${GREEN}${GET_NOTE_API_KEY:0:8}...${NC}"
echo -e "Topic ID: ${GREEN}${GET_NOTE_TOPIC_ID:-Not set}${NC}"
echo -e "API Base URL: ${GREEN}${GET_NOTE_API_BASE_URL}${NC}"
echo -e "Log Level: ${GREEN}${LOG_LEVEL}${NC}"
echo -e "Transport Mode: ${GREEN}${TRANSPORT_MODE}${NC}"
if [ "$TRANSPORT_MODE" != "stdio" ]; then
    echo -e "Server Address: ${GREEN}${SERVER_HOST}:${SERVER_PORT}${NC}"
fi
echo ""

# Confirm before starting
read -p "Start the server with these settings? (y/N): " confirm
if [[ ! "$confirm" =~ ^[Yy]$ ]]; then
    echo "Cancelled."
    exit 0
fi

# Export all environment variables
export GET_NOTE_API_KEY
export GET_NOTE_TOPIC_ID
export GET_NOTE_API_BASE_URL
export LOG_LEVEL

# Start the server with correct path
echo -e "${BLUE}🚀 Starting Get Notes MCP Server...${NC}"
echo "Command: node $PROJECT_ROOT/src/index.js $CMD_ARGS"
echo ""

cd "$PROJECT_ROOT"
exec node src/index.js $CMD_ARGS